import{_ as a}from"./chunks/system-management.G53wYALY.js";import{_ as n,o as s,c as r,a2 as e}from"./chunks/framework.Cd7uensT.js";const u=JSON.parse('{"title":"系统管理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/features/system-management.md","filePath":"guide/features/system-management.md","lastUpdated":1785486863000}'),l={name:"guide/features/system-management.md"};function o(d,t,i,p,h,c){return s(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="系统管理" tabindex="-1">系统管理 <a class="header-anchor" href="#系统管理" aria-label="Permalink to &quot;系统管理&quot;">​</a></h1><h2 id="用户管理" tabindex="-1">用户管理 <a class="header-anchor" href="#用户管理" aria-label="Permalink to &quot;用户管理&quot;">​</a></h2><p>用户管理用于管理系统用户账号和权限。</p><p><img src="'+a+`" alt="系统管理概览"></p><h3 id="用户状态" tabindex="-1">用户状态 <a class="header-anchor" href="#用户状态" aria-label="Permalink to &quot;用户状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态</th><th>说明</th></tr></thead><tbody><tr><td><strong>正常</strong></td><td>用户可正常登录系统并使用相应权限功能</td></tr><tr><td><strong>待审核</strong></td><td>新注册用户，等待管理员审核通过后方可登录</td></tr><tr><td><strong>已禁用</strong></td><td>账号被管理员禁用，无法登录系统</td></tr></tbody></table><h3 id="审核流程" tabindex="-1">审核流程 <a class="header-anchor" href="#审核流程" aria-label="Permalink to &quot;审核流程&quot;">​</a></h3><p>用户注册审核流程如下：</p><ol><li><strong>用户注册</strong>：新用户通过注册页面提交账号信息</li><li><strong>待审核状态</strong>：注册成功后，账号自动进入「待审核」状态</li><li><strong>管理员审核</strong>：管理员在「用户管理」页面查看待审核用户列表</li><li><strong>审核操作</strong>：管理员可「通过」或「驳回」注册申请，驳回需填写原因</li><li><strong>结果通知</strong>： <ul><li>审核通过：用户收到通知，账号状态变更为「正常」，可登录系统</li><li>审核驳回：用户收到通知及驳回原因，可根据原因修改后重新提交注册</li></ul></li></ol><h3 id="角色权限" tabindex="-1">角色权限 <a class="header-anchor" href="#角色权限" aria-label="Permalink to &quot;角色权限&quot;">​</a></h3><p>系统采用 RBAC（基于角色的访问控制）权限模型：</p><table tabindex="0"><thead><tr><th>角色</th><th>权限范围</th></tr></thead><tbody><tr><td><strong>管理员（admin）</strong></td><td>全部功能（通配符 <code>*</code>），包括系统设置、用户管理、数据管理、所有模块的增删改查</td></tr><tr><td><strong>运维人员</strong></td><td>设备管理（含导入导出、端口管理、接线管理）、工单处理（接单、处理、完成）</td></tr><tr><td><strong>普通用户</strong></td><td>查看权限（查看设备、工单、仪表盘等），可创建工单</td></tr></tbody></table><h3 id="角色管理" tabindex="-1">角色管理 <a class="header-anchor" href="#角色管理" aria-label="Permalink to &quot;角色管理&quot;">​</a></h3><blockquote><p>v2.4.0 新增「角色管理」独立页面，支持管理员自定义角色与权限分配。</p></blockquote><p>角色管理页面提供可视化的角色与权限配置功能：</p><h4 id="角色列表" tabindex="-1">角色列表 <a class="header-anchor" href="#角色列表" aria-label="Permalink to &quot;角色列表&quot;">​</a></h4><p>进入「系统管理」→「角色管理」，可查看系统所有角色：</p><ul><li>角色名称、角色编码、状态、创建时间</li><li>支持按角色名称搜索、按状态筛选</li><li>支持新增、编辑、删除角色</li><li>删除角色时需确保没有用户关联该角色</li></ul><h4 id="创建-编辑角色" tabindex="-1">创建/编辑角色 <a class="header-anchor" href="#创建-编辑角色" aria-label="Permalink to &quot;创建/编辑角色&quot;">​</a></h4><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th></tr></thead><tbody><tr><td><strong>角色名称</strong></td><td>角色显示名称，如「审计员」、「网络管理员」</td></tr><tr><td><strong>角色编码</strong></td><td>角色唯一标识（如 <code>auditor</code>），创建后不可修改</td></tr><tr><td><strong>排序</strong></td><td>控制角色在列表中的显示顺序</td></tr><tr><td><strong>状态</strong></td><td>启用/禁用，禁用后该角色下所有用户权限失效</td></tr></tbody></table><h4 id="权限配置" tabindex="-1">权限配置 <a class="header-anchor" href="#权限配置" aria-label="Permalink to &quot;权限配置&quot;">​</a></h4><p>系统采用 <strong>三级权限结构</strong>（模块→菜单→按钮），创建角色时按需勾选：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>模块级（第一层）       菜单级（第二层）        按钮级（第三层）</span></span>
<span class="line"><span>────────────────────────────────────────────────────</span></span>
<span class="line"><span>仪表盘                ├─ 查看仪表盘           └─ 导出数据</span></span>
<span class="line"><span>机房管理              ├─ 机房列表              ├─ 查看机房</span></span>
<span class="line"><span>                      │                       ├─ 新增机房</span></span>
<span class="line"><span>                      │                       ├─ 编辑机房</span></span>
<span class="line"><span>                      │                       └─ 删除机房</span></span>
<span class="line"><span>                      ├─ 机柜列表              ├─ 查看机柜</span></span>
<span class="line"><span>                      │                       ├─ 新增机柜</span></span>
<span class="line"><span>                      │                       └─ ...</span></span>
<span class="line"><span>                      ├─ 3D机柜可视化</span></span>
<span class="line"><span>                      └─ 机房平面图            └─ 编辑平面图</span></span>
<span class="line"><span>资产管理              ├─ 设备管理              ├─ 查看/新增/编辑/删除设备</span></span>
<span class="line"><span>                      │                       ├─ 导入/导出设备</span></span>
<span class="line"><span>                      ├─ 空闲设备              ├─ 上架/编辑/恢复/删除</span></span>
<span class="line"><span>                      ├─ 字段管理</span></span>
<span class="line"><span>                      ├─ 端口管理              ├─ 新增/编辑/删除端口</span></span>
<span class="line"><span>                      └─ 接线管理              ├─ 新增/编辑/删除接线</span></span>
<span class="line"><span>耗材管理              ├─ 耗材管理              ├─ ...</span></span>
<span class="line"><span>                      ├─ 耗材分类</span></span>
<span class="line"><span>                      └─ 耗材统计</span></span>
<span class="line"><span>工单管理              ├─ 工单管理              ├─ ...</span></span>
<span class="line"><span>                      └─ 工单统计</span></span>
<span class="line"><span>资产盘点              ├─ 盘点任务              ├─ ...</span></span>
<span class="line"><span>                      └─ 盘点记录</span></span>
<span class="line"><span>系统管理              ├─ 用户管理              ├─ 查看/新增/编辑/删除用户</span></span>
<span class="line"><span>                      ├─ 角色管理              ├─ 查看/新增/编辑/删除角色</span></span>
<span class="line"><span>                      ├─ 系统设置              ├─ 查看/编辑设置</span></span>
<span class="line"><span>                      └─ 系统字段              └─ ...</span></span>
<span class="line"><span>操作日志              ├─ 操作日志              └─ ...</span></span>
<span class="line"><span>备份管理              ├─ 备份管理              └─ ...</span></span>
<span class="line"><span>库房管理              ├─ 库房管理              └─ ...</span></span></code></pre></div><ul><li><strong>父子联动</strong>：勾选父级权限时，自动勾选其下所有子权限；取消子权限时，父级保持选中</li><li><strong>通配符支持</strong>：<code>*</code> 表示全部权限，<code>inventory:*</code> 表示盘点模块下的所有权限</li><li><strong>管理员角色</strong>：默认拥有所有权限（通配符 <code>*</code>），不可编辑权限范围</li></ul><h4 id="角色分配" tabindex="-1">角色分配 <a class="header-anchor" href="#角色分配" aria-label="Permalink to &quot;角色分配&quot;">​</a></h4><p>在「用户管理」→「编辑用户」页面中，通过多选下拉框为用户分配角色：</p><ul><li><strong>单用户多角色</strong>：用户权限 = 所有角色权限的并集</li><li><strong>变更即生效</strong>：角色分配修改后，用户下次请求时自动生效（无需重新登录）</li></ul><h2 id="系统设置" tabindex="-1">系统设置 <a class="header-anchor" href="#系统设置" aria-label="Permalink to &quot;系统设置&quot;">​</a></h2><p>系统设置用于配置系统全局参数，包含「基本设置」「邮件服务」「关于系统」三个标签页。</p><h3 id="基本设置" tabindex="-1">基本设置 <a class="header-anchor" href="#基本设置" aria-label="Permalink to &quot;基本设置&quot;">​</a></h3><p>基本设置包含站点信息、公司信息、安全设置等通用配置。</p><h4 id="站点信息" tabindex="-1">站点信息 <a class="header-anchor" href="#站点信息" aria-label="Permalink to &quot;站点信息&quot;">​</a></h4><table tabindex="0"><thead><tr><th>设置项</th><th>说明</th></tr></thead><tbody><tr><td><strong>站点名称</strong></td><td>系统浏览器标签页标题和页面左上角显示的名称</td></tr><tr><td><strong>Logo</strong></td><td>系统左上角显示的 Logo 图片，建议尺寸 120×40px，支持 PNG/SVG 格式</td></tr></tbody></table><h4 id="安全设置" tabindex="-1">安全设置 <a class="header-anchor" href="#安全设置" aria-label="Permalink to &quot;安全设置&quot;">​</a></h4><table tabindex="0"><thead><tr><th>设置项</th><th>说明</th></tr></thead><tbody><tr><td><strong>空闲超时</strong></td><td>用户无操作后自动退出登录的时间，可选范围：15分钟、30分钟、60分钟、永不超时</td></tr><tr><td><strong>背景图片</strong></td><td>登录页的背景图片，支持 JPG/PNG 格式</td></tr><tr><td><strong>维护模式</strong></td><td>开启后系统仅管理员可登录，其他用户访问时显示维护提示页面</td></tr><tr><td><strong>登录限制</strong></td><td>可限制指定 IP 段或仅允许内网 IP 访问系统登录页</td></tr></tbody></table><h3 id="邮件服务-管理员专属" tabindex="-1">邮件服务（管理员专属） <a class="header-anchor" href="#邮件服务-管理员专属" aria-label="Permalink to &quot;邮件服务（管理员专属）&quot;">​</a></h3><blockquote><p>v2.3.0 新增，仅管理员可见此标签页。</p></blockquote><p>邮件服务用于配置 SMTP 邮件发送，支持发送验证码邮件、测试邮件等功能。</p><h4 id="配置项" tabindex="-1">配置项 <a class="header-anchor" href="#配置项" aria-label="Permalink to &quot;配置项&quot;">​</a></h4><table tabindex="0"><thead><tr><th>设置项</th><th>说明</th></tr></thead><tbody><tr><td><strong>SMTP 服务器</strong></td><td>邮件发送服务器地址（如 smtp.example.com）</td></tr><tr><td><strong>端口</strong></td><td>SMTP 服务端口（465/587/25 等）</td></tr><tr><td><strong>加密方式</strong></td><td>SSL/TLS 加密方式</td></tr><tr><td><strong>发件人邮箱</strong></td><td>发件人邮箱地址</td></tr><tr><td><strong>发件人名称</strong></td><td>邮件发件人显示名称</td></tr><tr><td><strong>SMTP 用户名</strong></td><td>邮箱登录用户名</td></tr><tr><td><strong>SMTP 密码</strong></td><td>邮箱登录密码或授权码</td></tr></tbody></table><h4 id="操作说明" tabindex="-1">操作说明 <a class="header-anchor" href="#操作说明" aria-label="Permalink to &quot;操作说明&quot;">​</a></h4><ol><li>进入「系统管理」→「系统设置」→「邮件服务」标签</li><li>填写 SMTP 服务器配置信息</li><li>点击「保存」完成配置</li><li>（可选）点击「发送测试邮件」验证配置是否生效</li></ol><h3 id="关于系统" tabindex="-1">关于系统 <a class="header-anchor" href="#关于系统" aria-label="Permalink to &quot;关于系统&quot;">​</a></h3><p>关于系统页面提供系统版本信息和相关工具。</p><h4 id="系统信息" tabindex="-1">系统信息 <a class="header-anchor" href="#系统信息" aria-label="Permalink to &quot;系统信息&quot;">​</a></h4><ul><li><strong>系统名称</strong>：IDC 设备资产管理系统</li><li><strong>当前版本</strong>：显示当前运行的版本号</li><li><strong>部署环境</strong>：显示是否运行在 Docker 容器中</li></ul><h4 id="系统监控" tabindex="-1">系统监控 <a class="header-anchor" href="#系统监控" aria-label="Permalink to &quot;系统监控&quot;">​</a></h4><blockquote><p>v2.3.4 新增。系统首页「系统信息」卡片展示实时运行状态。</p></blockquote><p>系统监控信息通过系统设置页面「关于系统」标签页查看：</p><table tabindex="0"><thead><tr><th>指标</th><th>说明</th></tr></thead><tbody><tr><td><strong>CPU 使用率</strong></td><td>基于 <code>os.cpus().times</code> 差值计算，每 5 秒采样一次，跨平台准确获取</td></tr><tr><td><strong>内存使用率</strong></td><td>系统内存总量、已用、可用及百分比</td></tr><tr><td><strong>磁盘使用率</strong></td><td>系统磁盘空间概览</td></tr><tr><td><strong>数据库状态</strong></td><td>数据库类型（MySQL / SQLite）、版本号、连接状态</td></tr><tr><td><strong>运行时长</strong></td><td>进程已运行时间</td></tr><tr><td><strong>Node.js 版本</strong></td><td>运行环境版本</td></tr></tbody></table><blockquote><p>CPU 使用率采样器替代了 <code>os.loadavg()</code>（Windows 上始终返回 [0,0,0]），采用真实差值计算，确保 Linux 和 Windows 均准确。</p></blockquote><h4 id="在线更新" tabindex="-1">在线更新 <a class="header-anchor" href="#在线更新" aria-label="Permalink to &quot;在线更新&quot;">​</a></h4><blockquote><p>v2.3.2 新增。</p></blockquote><p>点击「检查更新」按钮，系统自动检测是否有新版本可用：</p><ul><li><strong>已是最新</strong>：绿色标识提示已是最新版本</li><li><strong>发现新版本</strong>：显示当前版本与最新版本对比，并提供更新指引 <ul><li>非 Docker 环境：显示终端命令提示（<code>cd 项目路径 &amp;&amp; node update.js</code>），支持一键复制</li><li>Docker 环境：提示拉取最新镜像后重建容器</li></ul></li><li>更新日志区域展示版本发布说明</li></ul><h4 id="开源许可" tabindex="-1">开源许可 <a class="header-anchor" href="#开源许可" aria-label="Permalink to &quot;开源许可&quot;">​</a></h4><blockquote><p>v2.3.2 新增。</p></blockquote><p>点击「开源许可」按钮，可查看系统前后端所有依赖包的开源许可信息：</p><ul><li>按许可类型分组统计（MIT、Apache-2.0、ISC 等）</li><li>列表展示：依赖名称、版本、许可类型、运行/开发分类、项目主页</li><li>支持分页浏览</li></ul><h3 id="操作说明-1" tabindex="-1">操作说明 <a class="header-anchor" href="#操作说明-1" aria-label="Permalink to &quot;操作说明&quot;">​</a></h3><ol><li>进入「系统管理」→「系统设置」页面</li><li>通过左侧标签导航切换不同设置模块</li><li>修改配置项后点击「保存」按钮</li><li>部分设置（如站点名称、Logo、空闲超时）保存后立即生效</li><li>维护模式和登录限制等安全设置保存后，下一次登录时生效</li></ol>`,61)])])}const q=n(l,[["render",o]]);export{u as __pageData,q as default};
